import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第八卦 比 水地比 坎上坤下","description":"周易 - 第八卦 比 水地比 坎上坤下","frontmatter":{"title":"第八卦 比 水地比 坎上坤下","description":"周易 - 第八卦 比 水地比 坎上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/009.md","filePath":"zh/classics/zhouyi/009.md"}'),l={name:"zh/classics/zhouyi/009.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="比" tabindex="-1">比 <a class="header-anchor" href="#比" aria-label="Permalink to “比”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>吉。原筮元永贞，无咎。不宁方来，后夫凶。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>比，吉也，比，辅也，下顺从也。原筮元永贞，无咎，以刚中也。不宁方来，上下应也。后夫凶，其道穷也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>地上有水，比；先王以建万国，亲诸侯。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>有孚比之，无咎。有孚盈缶，终 来有他，吉。象曰：比之初六，有他吉也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>比自内，贞吉。象曰：比之自内，不自失也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>比之匪人。象曰：比之匪人，不亦伤乎！</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>外比之，贞吉。象曰：外比於贤，以从上也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>显比，王用三驱，失前禽。邑人不诫，吉。象曰：显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>比之无首，凶。象曰：比之无首，无所终也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
